-- Test-only Stripe state. Never expose to Supabase client roles.
CREATE TABLE IF NOT EXISTS rentall."ContasStripeLocador" (
  "UserId" text PRIMARY KEY REFERENCES rentall."AspNetUsers"("Id") ON DELETE CASCADE,
  "AccountId" varchar(128) NOT NULL UNIQUE,
  "Pais" varchar(2) NOT NULL DEFAULT 'PT' CHECK("Pais"='PT'),
  "CriadaEm" timestamptz NOT NULL DEFAULT now()
);
CREATE TABLE IF NOT EXISTS rentall."PagamentosAluguer" (
  "Id" integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "PedidoId" integer NOT NULL UNIQUE REFERENCES rentall."PedidosAluguer"("Id") ON DELETE RESTRICT,
  "CompradorId" varchar(128) NOT NULL,
  "LocadorId" varchar(128) NOT NULL,
  "StripeAccountId" varchar(128) NOT NULL,
  "StripeSessionId" varchar(128) NOT NULL UNIQUE,
  "StripePaymentIntentId" varchar(128),
  "Moeda" varchar(3) NOT NULL DEFAULT 'eur' CHECK("Moeda"='eur'),
  "TotalCentimos" bigint NOT NULL CHECK("TotalCentimos" >= 50),
  "ComissaoCentimos" bigint NOT NULL CHECK("ComissaoCentimos" >= 0 AND "ComissaoCentimos" < "TotalCentimos"),
  "Estado" varchar(24) NOT NULL DEFAULT 'Checkout criado'
    CHECK("Estado" IN ('Checkout criado','Pago em teste','Expirado','Falhado')),
  "CriadoEm" timestamptz NOT NULL DEFAULT now(),
  "PagoEm" timestamptz,
  "AtualizadoEm" timestamptz
);
CREATE TABLE IF NOT EXISTS rentall."EventosStripeProcessados" (
  "EventId" varchar(128) PRIMARY KEY,
  "Tipo" varchar(100) NOT NULL,
  "ProcessadoEm" timestamptz NOT NULL DEFAULT now()
);
CREATE INDEX IF NOT EXISTS "IX_Pagamentos_Account" ON rentall."PagamentosAluguer"("StripeAccountId");
CREATE INDEX IF NOT EXISTS "IX_Pagamentos_Intent" ON rentall."PagamentosAluguer"("StripePaymentIntentId");
REVOKE ALL ON rentall."ContasStripeLocador",rentall."PagamentosAluguer",rentall."EventosStripeProcessados" FROM PUBLIC,anon,authenticated;
REVOKE ALL ON SEQUENCE rentall."PagamentosAluguer_Id_seq" FROM PUBLIC,anon,authenticated;
GRANT SELECT,INSERT,UPDATE ON rentall."ContasStripeLocador",rentall."PagamentosAluguer",rentall."EventosStripeProcessados" TO rentall_app;
GRANT USAGE,SELECT ON SEQUENCE rentall."PagamentosAluguer_Id_seq" TO rentall_app;
